"""German recipe generated by Claude from the entered ingredients."""

from typing import Any

from pydantic import ValidationError

from app.claude_cli import ClaudeCliError, run_claude
from app.models import IngredientLine, RecipeDetail

MODEL = "sonnet"
TIMEOUT_SECONDS = 120.0

OUTPUT_SCHEMA = {
    "type": "object",
    "properties": {
        "title": {"type": "string"},
        "ready_in_minutes": {"type": "integer"},
        "ingredients": {
            "type": "array",
            "items": {
                "type": "object",
                "properties": {
                    "name": {"type": "string"},
                    "amount": {"type": ["number", "null"]},
                    "unit": {"type": "string"},
                },
                "required": ["name", "amount", "unit"],
                "additionalProperties": False,
            },
        },
        "steps": {"type": "array", "items": {"type": "string"}},
    },
    "required": ["title", "ready_in_minutes", "ingredients", "steps"],
    "additionalProperties": False,
}

SYSTEM_PROMPT = (
    "You write one realistic home-cooking recipe in German. The input is JSON "
    'with "ingredients" (German, as entered by the cook) and "max_ready_time" '
    "(minutes or null). Use only the given ingredients plus spices, herbs, oil, "
    "salt, pepper, water, flour, sugar and similar pantry basics; you do not "
    "have to use every given ingredient. Write the title, ingredient names and "
    "steps in natural German as used in German cookbooks. Give metric amounts "
    "with German short units (g, ml, EL, TL, Stk, Prise) or an empty unit, and "
    "null as amount when no amount makes sense. Write each step as complete "
    "German sentences. ready_in_minutes is the total time in minutes and must "
    "not exceed max_ready_time when it is set."
)


class AiRecipeError(Exception):
    """The CLI failed or returned a recipe that does not pass validation."""


def validate_ai_output(output: Any, max_ready_time: int | None) -> RecipeDetail:
    """Validate the CLI output; raises AiRecipeError."""
    try:
        title = output["title"].strip()
        ready = output["ready_in_minutes"]
        ingredients = [
            IngredientLine(
                name=i["name"].strip(), amount=i["amount"], unit=i["unit"].strip()
            )
            for i in output["ingredients"]
        ]
        steps = [s.strip() for s in output["steps"]]
    except (KeyError, TypeError, AttributeError, ValidationError) as exc:
        raise AiRecipeError from exc
    if (
        not title
        # Not isinstance: a JSON true would pass as the int 1.
        or type(ready) is not int
        or ready < 1
        or (max_ready_time is not None and ready > max_ready_time)
        or not ingredients
        or not all(i.name for i in ingredients)
        or any(i.amount is not None and i.amount < 0 for i in ingredients)
        or not steps
        or not all(steps)
    ):
        raise AiRecipeError
    return RecipeDetail(
        source="ai",
        spoonacular_id=None,
        title=title,
        image=None,
        ready_in_minutes=ready,
        ingredients=ingredients,
        steps=steps,
    )


async def generate_recipe(
    ingredients: list[str], max_ready_time: int | None
) -> RecipeDetail:
    try:
        output = await run_claude(
            model=MODEL,
            system_prompt=SYSTEM_PROMPT,
            schema=OUTPUT_SCHEMA,
            payload={"ingredients": ingredients, "max_ready_time": max_ready_time},
            timeout=TIMEOUT_SECONDS,
        )
    except ClaudeCliError as exc:
        raise AiRecipeError from exc
    return validate_ai_output(output, max_ready_time)
